import type { EnvEnvSchema } from "@saflib/env/env";
import type { ViteEnvSchema } from "@saflib/vite/env";

/**
 * Environment variables for the `@sderickson/notebook-clients` package, including inherited variables via `extends`.
 * Generated by `@saflib/env`. To update, make changes to the adjacent `env.schema.json`, navigate to the package root, and run `npm exec saf-env generate`.
 */
export interface NotebookClientsEnvSchema extends EnvEnvSchema, ViteEnvSchema {}

/**
 * `process.env` casted to the `NotebookClientsEnvSchema` type.
 */
export const typedEnv = (globalThis.process
  ? process.env
  : {}) as unknown as NotebookClientsEnvSchema;
